template:
Short name: {{ interface | regex_replace('^GigabitEthernet', 'Gi') }}
Port: {{ interface | regex_search('[0-9]+/[0-9]+$') }}
Up interfaces: {{ output | regex_findall('^(Gi[0-9]+/[0-9]+) +up$', multiline=true) | join(', ') }}

{% set config = defaults | combine(overrides, recursive=true) -%}
MTU: {{ config.mtu }}
Logging: {{ config.logging.enabled }} / {{ config.logging.level }}
{% set records = ports | dict2items -%}
Interfaces: {{ records | map(attribute='key') | join(', ') }}
{% set restored = records | items2dict -%}
Uplink description: {{ restored['Gi0/1'] }}

Missing: {{ intended | difference(actual) | sort | join(', ') }}
Unexpected: {{ actual | difference(intended) | sort | join(', ') }}
Common: {{ intended | intersect(actual) | sort | join(', ') }}
All differences: {{ intended | symmetric_difference(actual) | sort | join(', ') }}
